{"cmd":"python3 - <<'PY'
import cv2, glob, csv, os, numpy as np

frames = sorted(glob.glob('/root/keyframes_*.png'))
if not frames:
    raise SystemExit('No keyframes found')

objects = {
    'coins': '/root/coin.png',
    'enemies': '/root/enemy.png',
    'turtles': '/root/turtle.png',
}

def count_matches(img, tmpl, thresh=0.9, min_dist=3):
    res = cv2.matchTemplate(img, tmpl, cv2.TM_CCOEFF_NORMED)
    ys, xs = np.where(res >= thresh)
    if len(xs) == 0:
        return 0
    scores = res[ys, xs]
    order = np.argsort(scores)[::-1]
    taken = []
    for idx in order:
        x, y = xs[idx], ys[idx]
        if all((x-tx)**2 + (y-ty)**2 >= min_dist**2 for tx, ty in taken):
            taken.append((x, y))
    return len(taken)

# Load templates once
templates = {}
for name, path in objects.items():
    tmpl = cv2.imread(path, cv2.IMREAD_GRAYSCALE)
    if tmpl is None:
        raise SystemExit(f'Failed to load template: {path}')
    templates[name] = tmpl

rows = []
for frame in frames:
    img = cv2.imread(frame, cv2.IMREAD_GRAYSCALE)
    if img is None:
        raise SystemExit(f'Failed to load frame: {frame}')
    counts = {name: count_matches(img, tmpl) for name, tmpl in templates.items()}
    rows.append({
        'frame_id': frame,
        'coins': counts['coins'],
        'enemies': counts['enemies'],
        'turtles': counts['turtles'],
    })

out_path = '/root/counting_results.csv'
with open(out_path, 'w', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=['frame_id', 'coins', 'enemies', 'turtles'])
    writer.writeheader()
    writer.writerows(rows)

print('Wrote', out_path)
